//! Runtime support for code generated by `#[tool]` and `#[tools]`, re-exported through
//! `strands::__private`.

use std::future::Future;
use std::sync::OnceLock;

use schemars::JsonSchema;
use serde::Serialize;
use serde::de::DeserializeOwned;

use crate::tools::function_tool::{InputValidator, wrap_in_tool_result};
use crate::tools::schema::input_schema_for;
use crate::tools::tool::{ToolContext, ToolError, ToolOutcome, ToolStream};
use crate::types::json::JsonValue;
use crate::types::tools::ToolSpec;

/// The spec and input validator of one generated tool, built once on first use.
#[derive(Debug, Default)]
pub struct LazyToolDef {
    def: OnceLock<ToolDef>,
}

impl LazyToolDef {
    /// An unbuilt definition, for a `static`.
    pub const fn new() -> Self {
        Self { def: OnceLock::new() }
    }

    /// The definition of a tool whose input is `I`.
    pub fn typed<I: JsonSchema>(&self, name: &str, description: &str) -> &ToolDef {
        self.def.get_or_init(|| {
            let schema = input_schema_for::<I>();
            ToolDef {
                validator: Some(InputValidator::new(&schema)),
                spec: ToolSpec::new(name, description).with_input_schema(schema),
            }
        })
    }

    /// The definition of a tool without parameters: the TS default schema, no validation.
    pub fn untyped(&self, name: &str, description: &str) -> &ToolDef {
        self.def.get_or_init(|| ToolDef {
            validator: None,
            spec: ToolSpec::new(name, description).with_input_schema(serde_json::json!({
                "type": "object",
                "properties": {},
                "additionalProperties": false,
            })),
        })
    }
}

/// A built tool definition.
#[derive(Debug)]
pub struct ToolDef {
    spec: ToolSpec,
    validator: Option<InputValidator>,
}

impl ToolDef {
    /// The tool spec.
    pub fn spec(&self) -> ToolSpec {
        self.spec.clone()
    }

    /// Validates and parses the input, then runs `call`; failures become error results.
    pub fn run<I, F, Fut>(&self, context: ToolContext, call: F) -> ToolStream
    where
        I: DeserializeOwned + Send + 'static,
        F: FnOnce(I, ToolContext) -> Fut + Send + 'static,
        Fut: Future<Output = Result<JsonValue, ToolError>> + Send + 'static,
    {
        let input = context.tool_use().input().clone();
        let parsed = match &self.validator {
            Some(validator) => validator.parse::<I>(input),
            None => serde_json::from_value(input).map_err(ToolError::from),
        };
        finish(
            context,
            move |context| async move { call(parsed?, context).await },
        )
    }

    /// Runs `call` without reading the input, as TS does for tools without an input schema.
    pub fn run_without_input<F, Fut>(&self, context: ToolContext, call: F) -> ToolStream
    where
        F: FnOnce(ToolContext) -> Fut + Send + 'static,
        Fut: Future<Output = Result<JsonValue, ToolError>> + Send + 'static,
    {
        finish(context, call)
    }
}

fn finish<F, Fut>(context: ToolContext, call: F) -> ToolStream
where
    F: FnOnce(ToolContext) -> Fut + Send + 'static,
    Fut: Future<Output = Result<JsonValue, ToolError>> + Send + 'static,
{
    let tool_use_id = context.tool_use().tool_use_id().to_owned();
    ToolStream::from_future(async move {
        match call(context).await {
            Ok(value) => ToolOutcome::Result(wrap_in_tool_result(value, &tool_use_id)),
            Err(error) => error.into_outcome(&tool_use_id),
        }
    })
}

/// A `Result` return value as tool output.
///
/// # Errors
///
/// The function's error, or a serialization failure.
pub fn result_output<T: Serialize, E: Into<ToolError>>(result: Result<T, E>) -> Result<JsonValue, ToolError> {
    Ok(serde_json::to_value(result.map_err(Into::into)?)?)
}

/// A plain return value as tool output.
///
/// # Errors
///
/// A serialization failure.
pub fn value_output<T: Serialize>(value: T) -> Result<JsonValue, ToolError> {
    Ok(serde_json::to_value(value)?)
}

/// Runs a sync tool body on a blocking thread, in the current span. A panic resumes on the
/// awaiting task, so the executor handles it like a panic in an async tool.
///
/// # Errors
///
/// The blocking task was cancelled (the runtime is shutting down).
pub async fn blocking<R: Send + 'static>(body: impl FnOnce() -> R + Send + 'static) -> Result<R, ToolError> {
    let span = tracing::Span::current();
    let task = tokio::task::spawn_blocking(move || span.in_scope(body));
    match task.await {
        Ok(value) => Ok(value),
        Err(error) if error.is_panic() => std::panic::resume_unwind(error.into_panic()),
        Err(error) => Err(error.into()),
    }
}

